#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n;
    long long k;
    cin >> n >> k;

    vector<int> posOne;
    for (int i = 0; i < 61; i++) {
        if ((k & (1LL << i)) != 0) {
            posOne.push_back(i);
        }
    }

    int numOne = posOne.size();
    long long states = 1LL << numOne; // 2^x
    vector<long long> res;

    // 枚举所有非空子集，掩码从 1 开始
    for (int i = 1; i < states; i++) {
        long long now = 0;
        for (int j = 0; j < numOne; j++) {
            if (i & (1 << j)) {
                now += (1LL << posOne[j]);
            }
        }
        res.push_back(now);
        if ((int)res.size() == n) {
            break;
        }
    }

    if ((int)res.size() < n) {
        cout << "NO" << endl;
    } else {
        // 最后一位设为 k，保证或和等于 k 并保持递增
        res[n - 1] = k;
        cout << "YES" << endl;
        for (long long val : res) {
            cout << val << " ";
        }
        cout << endl;
    }

    return 0;
}
